package net.officefloor.hq.app.person;


/**
 * A person, as the screen reads it (their grade the one in force on the sheet's today), with their statement count, and the last statement's due-total
 * and date ("" before the first), whether they are retired and the date they are retired from
 * ("" when not), whether they have any hold, their holds (in the order added), the ids of the people they name as patrons (in the order named) with their
 * shares (see {@link #shares}), and every
 * grade they have been given with the date it is from (the first "", from the beginning of time),
 * by from-date, their own terms in days in force on the sheet's today ("" for none), their contact ("" for none), their tags (sorted; none: empty), their aliases
 * (in the order given), and whether they clash: their name or an alias is a name or alias on another
 * sheet of the sheet's tree, the sheet they were transferred from ("" when never transferred), and
 * the retirements they were unretired from, oldest first, each as "<from> to <to>", and their snapshot lines, oldest first, each as
 * "<the day being left> <due-total>", and their statements still standing, oldest first (by date), each as
 * "<statement date> <due-total>", and their flag's reason while it is in force on the sheet's today ("" otherwise),
 * and the user who may approve or reject their PENDING claims as a steward may ("" for none).
 */
public record PersonResponse(String id, String name, String grade, long version, int statementCount,
        String statedTotal, String statementDate, boolean retired, String retiredFrom,
        boolean held, List<HoldFrom> holds, java.util.List<String> patronIds, List<String> patronShares, List<GradeFrom> grades, String terms,
        String contact, List<String> tags, List<String> aliases, boolean clashing, String origin, List<String> retirements,
        List<String> snapshots, List<String> statementLines, String flag,
        String approver) {

    /** A hold from a date to a date (yyyy-MM-dd; to "" when open-ended), both inclusive. */
    public record HoldFrom(String from, String to) {}

    /** A grade in force from a date (yyyy-MM-dd; "" from the beginning of time). */
    public record GradeFrom(String from, String grade) {}

    /**
     * The patrons' shares, in the order named: 100.00 split equally among {@code count} patrons, each
     * rounded half to even to two decimals, the remainder (100.00 less the shares added up) to the first.
     */
    static List<String> shares(int count) {
        if (count == 0) return List.of();
        BigDecimal whole = new BigDecimal("100.00");
        BigDecimal each = whole.divide(BigDecimal.valueOf(count), 2, RoundingMode.HALF_EVEN);
        List<String> shares = new ArrayList<>();
        shares.add(whole.subtract(each.multiply(BigDecimal.valueOf(count - 1))).toPlainString());
        for (int i = 1; i < count; i++) shares.add(each.toPlainString());
        return shares;
    }

    /** The person as the screen reads it on the sheet's today: their grade is the one in force on it. */
    public static PersonResponse from(Person person, LocalDate today, boolean clashing) {
        List<GradeFrom> grades = new ArrayList<>();
        grades.add(new GradeFrom("", person.getGrade()));
        person.getDatedGrades().forEach((from, grade) -> grades.add(new GradeFrom(from.toString(), grade)));
        return new PersonResponse(String.valueOf(person.getId()), person.getName(), person.gradeOn(today),
                person.getVersion(), person.getStatementCount(),
                person.getStatedTotal() == null ? "" : person.getStatedTotal(),
                person.getStatementDate() == null ? "" : person.getStatementDate().toString(),
                person.isRetired(), person.getRetiredFrom() == null ? "" : person.getRetiredFrom().toString(),
                person.isHeld(),
                person.getHolds().stream().map((h) -> new HoldFrom(h.from().toString(), h.to() == null ? "" : h.to().toString())).toList(),
                person.getPatronIds().stream().map(String::valueOf).toList(), shares(person.getPatronIds().size()), grades,
                person.termsOn(today) == null ? "" : person.termsOn(today).toString(),
                person.getContact() == null ? "" : person.getContact(), person.tagList(), List.copyOf(person.getAliases()), clashing,
                person.getOriginSheet() == null ? "" : person.getOriginSheet(),
                person.getPastRetirements().stream().map((r) -> r.from() + " to " + r.to()).toList(),
                List.copyOf(person.getSnapshots()), List.copyOf(person.getStatementLines()),
                person.flaggedOn(today) ? person.getFlagReason() : "",
                person.getApprover() == null ? "" : person.getApprover());
    }
}
package net.officefloor.hq.app.claim;


/**
 * A claim, as the screen reads it: its amount with two decimals, its date as yyyy-MM-dd and its
 * status, its number ("" when it has none), and its due as fixed when it was settled ("" while
 * its due is live), and who opened it ("" until it is opened); whether its person's last
 * statement bound it, and the figure it was bound to ("" when not stated, n/a when it had none);
 * and the number of the claim it corrects ("" when it is no correction); and the date its figures
 * round by (a correction's is the date of the claim it corrects); and its due-by as yyyy-MM-dd, fixed
 * when it was made; and its status log, oldest first, one line per status it has had as
 * {@code <STATUS> by <user> on <date> due=<due>}; and the date it is deferred until as yyyy-MM-dd
 * ("" when it was never deferred; it is deferred only while unbound by a statement and the sheet's today is before it);
 * and how many proofs it has had added; and the number of the claim it was split off ("" when none);
 * and the user whose open editor locks it on the sheet's today ("" when no one's does);
 * and whether it was added while its period was soft-closed; and the last sheet's today it was reminded
 * as yyyy-MM-dd ("" when never); and its external reference ("" when none); and its tags, sorted (none: empty); and the reason it was voided with ("" when none); and its comments, oldest first, as
 * {@code <user> on <date>: <text>}; and the number of the bulk settle batch that settled it ("" when none did);
 * and its lines, oldest first, as {@code <label> <qty> x <unit>}; and its review day, the sheet's today when it
 * went to REVIEW, as yyyy-MM-dd ("" when it never did); and whether a steward waived its late charge; and the
 * late charge its statement bound it to with its figure ("" when none is bound); and how many of its proofs are
 * receipts and how many photos; and whether it is held; and its shares, oldest first;
 * and the user assigned to review it ("" when none).
 */
public record ClaimResponse(String id, String personId, String amount, String date, String note,
        String status, String number, String due, String openedBy, boolean stated,
        String statedDue, String corrects, String roundDate, String dueBy, List<String> log, String deferredUntil,
        int proofs, String splitFrom, String lockedBy, boolean lateEntry, String remindedOn, String ref,
        List<String> tags, String voidReason, List<String> comments, String batch, List<String> lines, String reviewOn, boolean waived,
        String statedLate, int proofReceipts, int proofPhotos, boolean held, List<Shared> shares,
        String reviewUser, String pendingOn) {

    /** A share of the claim as the screen reads it: the holder's person id and their percent, two decimals. */
    public record Shared(String personId, String share) {
    }

    public static ClaimResponse from(Claim claim) {
        return from(claim, List.of(), List.of(), List.of());
    }

    public static ClaimResponse from(Claim claim, List<String> log, List<String> comments, List<String> lines) {
        return from(claim, log, comments, lines, List.of());
    }

    public static ClaimResponse from(Claim claim, List<String> log, List<String> comments, List<String> lines,
            List<ClaimShare> shares) {
        return new ClaimResponse(String.valueOf(claim.getId()), String.valueOf(claim.getPersonId()),
                claim.getAmount().toPlainString(), claim.getDate().toString(), claim.getNote(),
                claim.getStatus().name(),
                claim.getNumber() == null ? "" : claim.getNumber(),
                claim.getSettledDue() == null ? "" : claim.getSettledDue().toPlainString(),
                claim.getOpenedBy() == null ? "" : claim.getOpenedBy(),
                claim.isStated(),
                !claim.isStated() ? "" : claim.getStatedDue() == null ? "n/a" : claim.getStatedDue().toPlainString(),
                claim.getCorrects() == null ? "" : claim.getCorrects(),
                claim.getRoundDate().toString(), claim.getDueBy().toString(), log,
                claim.getDeferredUntil() == null ? "" : claim.getDeferredUntil().toString(),
                claim.getProofs(),
                claim.getSplitFrom() == null ? "" : claim.getSplitFrom(),
                claim.getLockedBy() == null ? "" : claim.getLockedBy(),
                claim.isLateEntry(),
                claim.getRemindedOn() == null ? "" : claim.getRemindedOn().toString(),
                claim.getRef() == null ? "" : claim.getRef(),
                claim.tagList(),
                claim.getVoidReason() == null ? "" : claim.getVoidReason(),
                comments,
                claim.getSettleBatch() == null ? "" : String.valueOf(claim.getSettleBatch()),
                lines,
                claim.getReviewOn() == null ? "" : claim.getReviewOn().toString(),
                claim.isWaived(),
                claim.getStatedLate() == null ? "" : claim.getStatedLate().toPlainString(),
                claim.getProofReceipts(), claim.getProofPhotos(), claim.isHeld(),
                shares.stream().map((s) -> new Shared(String.valueOf(s.personId()), s.share().toPlainString())).toList(),
                claim.getReviewUser() == null ? "" : claim.getReviewUser(),
                claim.getPendingOn() == null ? "" : claim.getPendingOn().toString());
    }
}
