 * overdue when this is before the sheet's today, and its late charge's 30-day boundaries are counted
 * from it. Its due-by as shown stays as it is.
 */
export function overdueFrom(claim: Claim, grade: string, late: Late): string {
  const grace = late.grace[grade];
  const days = grace ? valueOn(grace, claim.date) : '';
  return days === '' ? claim.dueBy : addDays(claim.dueBy, Number(days));
}

/**
 * Whether a claim's live figures round half up: by the rounding mode in force on the date it rounds
 * by when there is one; else it rounds by a date (its own, or for a correction
 * the date of the claim it corrects) before the sheet's policy date (its today when blank); on or
 * after it they round half to even.
 */
export function roundsHalfUp(claim: Claim, late: Late): boolean {
  const mode = valueOn(late.rounding, claim.roundDate || claim.date);
  if (mode !== '') return mode === 'half-up';
  const policy = late.policyDate !== '' ? late.policyDate : late.today;
  return (claim.roundDate || claim.date) < policy;
}

/** Whole days from one date (yyyy-MM-dd) to another, worked in UTC so no zone shifts it. */
export function daysBetween(from: string, to: string): number {
  const utc = (date: string) => {
    const [y, m, d] = date.split('-').map(Number);
    return Date.UTC(y, m - 1, d);
  };
  return Math.round((utc(to) - utc(from)) / 86_400_000);
}

/** A date (yyyy-MM-dd) some whole days on, worked in UTC so no zone shifts it. */
export function addDays(date: string, days: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

/**
 * A claim's late charge on its `figure`: for an OPEN or PENDING claim past its due-by (fixed when it was
 * made) plus its grade's grace ({@link overdueFrom}) on the sheet's today, for every full 30 days it is
 * overdue the late percent in force on that boundary date (that day plus 30, 60, 90 ... days) of the figure plus the
 * charges of the boundaries before it (compounding), each rounded as the claim rounds, added up; else nothing (as for a claim deferred on the sheet's today, or one whose late charge a steward waived, whatever its overdue state). While a statement binds it with a late charge, that charge, whatever the
 * sheet's today; else it follows the sheet's today.
 */
function lateCharge(claim: Claim, figure: string, late: Late, grade: string): bigint {
  if (!isOpen(claim) || isDeferred(claim, late.today) || figure === NA || late.today === '' || isCorrection(claim) || claim.waived) return 0n;
  if (isBound(claim) && claim.statedLate !== '') return hundredths(claim.statedLate);
  const from = overdueFrom(claim, grade, late);
  const overdue = daysBetween(from, late.today);
  const periods = overdue > 0 ? Math.floor(overdue / 30) : 0;
  const halfUp = roundsHalfUp(claim, late);
  let charge = 0n;
  for (let k = 1; k <= periods; k++) {
    const pct = valueOn(late.pct, addDays(from, 30 * k));
    if (hundredths(pct) !== 0n) charge += percentOf(showCents(hundredths(figure) + charge), pct, 1n, halfUp);
  }
  return charge;
}

/** A share (a percent, two decimals) of a two-decimal figure, rounded half to even. */
export function shareOf(figure: string, share: string): string {
  return showCents(percentOf(figure, share, 1n, false));
}

/** Due values added up, skipping n/a. */
export function sumDue(values: string[]): string {
  return showCents(values.filter((v) => v !== NA).reduce((n, v) => n + hundredths(v), 0n));
}

/** One two-decimal figure minus another, two decimals, a minus sign when negative. */
export function diffDue(value: string, previous: string): string {
  return showCents(hundredths(value) - hundredths(previous));
}

/**
 * People's figures added up as a sheet's total, skipping n/a: with three or more figures, the single
 * highest and the single lowest are left out.
 */
export function trimmedSumDue(values: string[]): string {
  const figures = values.filter((v) => v !== NA).map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const kept = figures.length >= 3 ? figures.slice(1, -1) : figures;
  return showCents(kept.reduce((n, v) => n + v, 0n));
}

/**
 * A claim's due: the one fixed when it was settled (its late charge frozen in), else its live due:
 * its floored figure (the one its person's last statement bound it to (OPEN or PENDING alike), else
 * the greater of the sheet's `floor` in force on its date and its amount at the rate in force on its
 * date) plus the late charge an overdue claim gains on that floored figure (by the grace of its
 * `grade`, the one in force on its date). A correction takes no floor; n/a stays n/a.
 */
export function claimDue(claim: Claim, pct: string | null, floor: Dated, late: Late, grade: string): string {
  if (claim.due !== '') return claim.due;
  const figure = isBound(claim)
    ? claim.statedDue
    : due(claim.amount, pct, isCorrection(claim) ? null : valueOn(floor, claim.date), roundsHalfUp(claim, late));
  if (figure === NA) return figure;
  return showCents(hundredths(figure) + lateCharge(claim, figure, late, grade));
}

/**
 * A person's due-total: the figures of their claims that count (an unbound OPEN one not when dated within one of `holds`: a retired person's, see `liveHolds`) (each at the rate in force on its
 * date for their grade in force on its date), added up, skipping n/a. With no rate for their grade
 * today it is n/a, unless a claim that counts keeps a fixed figure (settled, or bound by a
 * statement), has a figure under another grade in force on its date, or has a figure dated on or
 * before today (under a rate that has since ended). A shared claim counts its due less its holders'
 * parts, and the parts of others' claims shared with them count too (and keep it from n/a): both come in
 * `held` (see `heldParts`). Held to
 * the `cap` in force on the date of their latest claim that counts (see `capFor`) less their `cut` total (not below 0.00);
 * n/a is not capped.
 */
export function personDueTotal(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
  dated: Dated,
  held: HeldPart[] = [],
  cut = '0.00',
): string {
  const total = uncappedDueTotal(rates, grades, today, claims, holds, floor, late, held);
  const cap = capFor(dated, claims, holds, today);
  if (total === NA || cap === '') return total;
  const left = hundredths(cap) - hundredths(cut);
  const room = left > 0n ? left : 0n;
  return hundredths(total) <= room ? total : showCents(room);
}

/**
 * A person's cap ('' for none): the sheet's cap in force on the date of their latest claim that counts;
 * none while no claim of theirs counts.
 */
export function capFor(cap: Dated, claims: Claim[], holds: Hold[], today: string): string {
  const latest = claims.filter((c) => counts(c, holds, today)).reduce((d, c) => (c.date > d ? c.date : d), '');
  return latest === '' ? '' : valueOn(cap, latest);
}

/**
 * How far a person's due-total, before their cap ('' for none, see `capFor`), plus their `cut` total goes above
 * the cap: 0.00 when it does not.
 */
export function personExcess(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
  dated: Dated,
  held: HeldPart[] = [],
  cut = '0.00',
): string {
  const total = uncappedDueTotal(rates, grades, today, claims, holds, floor, late, held);
  const cap = capFor(dated, claims, holds, today);
  if (total === NA || cap === '') return '0.00';
  const figures = hundredths(total) + hundredths(cut);
  return figures <= hundredths(cap) ? '0.00' : showCents(figures - hundredths(cap));
}

function uncappedDueTotal(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
  held: HeldPart[],
): string {
  const counted = claims.filter((c) => counts(c, holds, today));
  const grade = gradeOn(grades, today);
  const kept = (c: Claim) => c.due !== '' || (isBound(c) && c.statedDue !== NA)
    || (gradeOn(grades, c.date) !== grade && rateOn(rates, gradeOn(grades, c.date), c.date, c.id) !== null)
    || (c.date <= today && rateOn(rates, gradeOn(grades, c.date), c.date, c.id) !== null);
  if (rateOn(rates, grade, today) === null && !counted.some(kept) && held.every((h) => h.given)) return NA;
  const own = counted.map((c) => claimDue(c, rateOn(rates, gradeOn(grades, c.date), c.date, c.id), floor, late, gradeOn(grades, c.date)));
  return sumDue([...own, ...held.map((h) => h.due)]);
}

/**
 * A part of a shared claim and the claim's status: a holder's part of a claim shared with them, or,
 * `given`, minus the parts its holders take of one of the person's own claims (so their own claim counts
 * its due less those parts).
 */
export type HeldPart = { due: string; status: ClaimStatus; given?: boolean };

/**
 * A holder's part of a claim whose due is `due`: a settled claim keeps its parts as frozen (its due times
 * their share / 100, rounded half to even); else the claim's amount times their share / 100, times the
 * rate of the holder's own grade in force on the claim's date / 100, rounded like the claim. Null when
 * their grade has no rate then (a part of 0.00 to the claim's own person).
 */
export function holderPart(claim: Claim, due: string, share: string, holder: Person | undefined, rates: Rate[], late: Late): string | null {
  if (claim.due !== '') return shareOf(due, share);
  if (!holder) return null;
  const pct = rateOn(rates, gradeOn(holder.grades, claim.date), claim.date, claim.id);
  if (pct === null) return null;
  return showCents(roundCents(hundredths(claim.amount) * hundredths(share) * hundredths(pct), 100000000n, roundsHalfUp(claim, late)));
}

/**
 * The parts a person holds of others' claims shared with them, and, given, minus the parts others hold
 * of their own shared claims, each claim counting as it does for its own person (at its rate, by its own
 * person's grade and holds), skipping n/a and holders whose grade has no rate.
 */
export function heldParts(
  personId: string,
  people: Person[],
  claims: Claim[],
  rates: Rate[],
  today: string,
  floor: Dated,
  late: Late,
): HeldPart[] {
  const parts: HeldPart[] = [];
  for (const c of claims) {
    if (c.shares.length === 0) continue;
    const share = c.shares.find((s) => s.personId === personId);
    if (!share && c.personId !== personId) continue;
    const owner = people.find((p) => p.id === c.personId);
    if (!owner || !counts(c, liveHolds(owner, today), today)) continue;
    const grade = gradeOn(owner.grades, c.date);
    const due = claimDue(c, rateOn(rates, grade, c.date, c.id), floor, late, grade);
    if (due === NA) continue;
    const partOf = (s: ClaimShare) => holderPart(c, due, s.share, people.find((p) => p.id === s.personId), rates, late);
    if (c.personId === personId) {
      const given = c.shares.reduce((n, s) => n + hundredths(partOf(s) ?? '0.00'), 0n);
      parts.push({ due: showCents(-given), status: c.status, given: true });
    } else if (share) {
      const part = partOf(share);
      if (part !== null) parts.push({ due: part, status: c.status });
    }
  }
  return parts;
}


/**
 * A person's due-total split by status, before the sheet's cap: their settled-total (the dues of
 * their SETTLED claims that count, at their frozen figures, corrections included) and their
 * open-total (the dues of their OPEN and PENDING claims that count), each added up, skipping n/a. A
 * shared claim counts its due less its holders' parts, and the parts of others' claims count too: both
 * come in `held` (see `heldParts`).
 */
export function personSplitTotals(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
  held: HeldPart[] = [],
): { settled: string; open: string } {
  const counted = claims.filter((c) => counts(c, holds, today));
  const dueOf = (c: Claim) => claimDue(c, rateOn(rates, gradeOn(grades, c.date), c.date, c.id), floor, late, gradeOn(grades, c.date));
  const heldIn = (statuses: ClaimStatus[]) => held.filter((h) => statuses.includes(h.status)).map((h) => h.due);
  return {
    settled: sumDue([...counted.filter((c) => c.status === 'SETTLED').map(dueOf), ...heldIn(['SETTLED'])]),
    open: sumDue([...counted.filter(isOpen).map(dueOf), ...heldIn(['OPEN', 'PENDING'])]),
  };
}

package net.officefloor.hq.app.setting;


/**
 * A sheet's settings. The figure settings are dated ({@code dated}, by key, each value from a
 * from-date; a blank value is "none"): its clerk limit, the highest due a clerk may settle (none: no
 * limit), and its clerk limit per grade (none: the sheet's), its floor, the least a claim's live due may be, and its terms, the days after a claim's
 * date that it is due by, and its late percent, what an overdue claim's due gains per full 30 days
 * overdue, and its terms per grade (a grade with none uses the sheet's terms), and its cap (none:
 * no cap), the most a person's due-total may be, and its proof threshold (none: none), above which a
 * claim's due, on the claim's date, needs a proof before it is settled or approved, and its note
 * threshold (none: none), above which a claim's due, on the claim's date, needs a note before it is opened, and
 * its rounding mode (half-up or half-even; none: by the policy date), how a claim dated then rounds, and
 * its proof threshold per grade (none: the sheet's proof threshold), and its review threshold (none: none),
 * above which a claim's due, on the claim's date, sends it to REVIEW when it is opened. The value in force on a date is the one with the
 * latest from-date on or before it; before every from-date the starting value (floor 1.00, late
 * percent 0.00, terms 14; none for the others). A claim takes its floor and late percent on
 * its date, and its terms on the day it was made, and its clerk limit on its date; a person's cap is the one in force on the date of
 * their latest claim that counts. The policy settings (the rounding mode, the floor, the cap, the terms, the late percent
 * and the clerk limit) are versioned together: every change to one of them is a new policy version ({@code versions},
 * the from-date of each in the order made; null: none, counting always).
 * Not dated: its policy date (null: the sheet's today): a claim dated before it rounds half up, one
 * on or after it half to even, and its period numbering from (null: off): while the sheet's today
 * is on or after it, a claim opened is numbered within its period, and its permission matrix
 * ({@code perms}, by action, the roles that may take it as a comma separated list; blank or missing:
 * the standing rule, open, settle, void, close and changing the sheet's today ({@code today}) by clerk and
 * steward, reassign and reopen by steward),
 * and its grace days (null: off): when the sheet's today is changed, every open period whose to-date
 * plus the grace days is before the new today is closed, and its entry date (null: off): while it is
 * set, the date of a new claim left undated instead of the sheet's today, and its pot (null: none),
 * shared out as cuts among a balanced pool's members, and its fiscal year start month (null: 1), and its alert threshold (null: off),
 * and its escalation gap in days (null: off), and its review SLA in days (null: none): a REVIEW claim whose
 * review day plus it is before the sheet's today is late for review, and its proof kinds (null: none), a
 * comma separated list of kinds: while set, a claim that needs a proof needs at least one of each, and its
 * default grade (null: A), the grade a quick-added person and an imported line with a blank grade take, and
 * its score thresholds, mid and high (null: none): while both are set, each person shows a band by their score, and
 * its score log switch (false: off): while it is on, changing the sheet's today writes a SCORE line per person, and
 * its maximum of open claims per person (null: none): opening a claim is refused while its person already has that
 * many OPEN or PENDING claims.
 */
public record Settings(String sheetId, LocalDate today, Map<String, NavigableMap<LocalDate, String>> dated,
        LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, String> perms, Integer graceDays,
        LocalDate entryDate, BigDecimal pot, Integer fiscalStartMonth, BigDecimal alertThreshold,
        Integer escalateAfter, Integer reviewSla, String proofKinds, String defaultGrade, Integer scoreMid,
        Integer scoreHigh, boolean scoreLog, Integer maxOpen, Integer pendingSla) {
    /** The grade a new person takes when none is given: the default grade, else A. */
    public String newPersonGrade() {
        return defaultGrade == null || defaultGrade.isBlank() ? "A" : defaultGrade;
    }

    /** The month, 1 to 12, a fiscal year starts in. */
    public int fiscalStart() {
        return fiscalStartMonth == null ? 1 : fiscalStartMonth;
    }

    /** The name, FY<yyyy>, of the fiscal year a date falls in: by the calendar year of its first day. */
    public String fiscalYearOf(LocalDate date) {
        return "FY" + (date.getMonthValue() >= fiscalStart() ? date.getYear() : date.getYear() - 1);
    }

    /** The grades every sheet has; a sheet may add more (see GradeRepository). */
    public static final List<String> GRADES = List.of("A", "B", "C");

    /** Whether a code is shaped as a grade: one to three capital letters. */
    public static boolean isGradeCode(String grade) {
        return grade != null && grade.matches("[A-Z]{1,3}");
    }

    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String FLOOR = "floor";
    public static final String TERMS = "terms";
    public static final String LATE_PCT = "late-pct";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";
    public static final String NOTE_THRESHOLD = "note-threshold";
    public static final String ALERT_THRESHOLD = "alert-threshold";
    public static final String ESCALATE_AFTER = "escalate-after";
    public static final String REVIEW_SLA = "review-sla";
    public static final String ROUNDING = "rounding";
    public static final String REVIEW_THRESHOLD = "review-threshold";
    public static final String PROOF_KINDS = "proof-kinds";
    public static final String DEFAULT_GRADE = "default-grade";
    public static final String SCORE_MID = "score-mid";
    public static final String SCORE_HIGH = "score-high";
    public static final String SCORE_LOG = "score-log";
    public static final String MAX_OPEN = "max-open";
    public static final String PENDING_SLA = "pending-sla";

    /** The policy settings, versioned together: every change to one of them is a new policy version. */
    public static final java.util.Set<String> POLICY_KEYS = java.util.Set.of(ROUNDING, FLOOR, CAP, TERMS, LATE_PCT, CLERK_LIMIT);

    /** The value the score log switch is recorded and shown as while it is on. */
    public static final String ON = "on";

    /** The kinds of proof the proof kinds list (none set: none). */
    public List<String> proofKindList() {
        if (proofKinds == null || proofKinds.isBlank()) return List.of();
        return java.util.Arrays.stream(proofKinds.split(",")).map(String::trim).filter((k) -> !k.isEmpty()).toList();
    }

    /** The rounding modes a sheet may set, as they are recorded. */
    public static final String HALF_UP = "half-up";
    public static final String HALF_EVEN = "half-even";

    /** The actions of the permission matrix, in the order they are shown and audited. */
    public static final List<String> ACTIONS = List.of("open", "settle", "void", "reassign", "close", "reopen", "today");

    /** The key of an action's entry in the permission matrix. */
    public static String permKey(String action) {
        return "perm-" + action;
    }

    /** The roles that may take an action by the standing rule. */
    public static List<String> standingRoles(String action) {
        return "reassign".equals(action) || "reopen".equals(action) || "lock".equals(action) ? List.of("steward") : List.of("clerk", "steward");
    }

    /** The roles that may take an action: its entry in the permission matrix, else the standing rule. */
    public List<String> rolesFor(String action) {
        String entry = perms == null ? null : perms.get(action);
        if (entry == null || entry.isBlank()) return standingRoles(action);
        return java.util.Arrays.stream(entry.split(",")).map(String::trim).filter((r) -> !r.isEmpty()).toList();
    }

    /** Whether a role may take an action. */
    public boolean allows(String action, String role) {
        if (net.officefloor.hq.app.role.Role.VIEWER.equals(role)) return false; // a viewer changes nothing
        if (net.officefloor.hq.app.role.Role.RESTRICTED.equals(role)) role = net.officefloor.hq.app.role.Role.CLERK; // acts as a clerk
        return rolesFor(action).contains(role);
    }

    /** The key of a grade's own terms. */
    public static String gradeTermsKey(String grade) {
        return "terms-" + grade;
    }

    /** The key of a grade's grace days. */
    public static String gradeGraceKey(String grade) {
        return "grace-" + grade;
    }

    /** The key of a grade's own proof threshold. */
    public static String gradeProofThresholdKey(String grade) {
        return "proof-threshold-" + grade;
    }

    /** A grade's own proof threshold in force on a date, or null when it has none. */
    public BigDecimal gradeProofThresholdOn(String grade, LocalDate date) {
        return figureOn(gradeProofThresholdKey(grade), date);
    }

    /** A grade's grace days in force on a date, or null when it has none. */
    public Integer gradeGraceOn(String grade, LocalDate date) {
        String value = valueOn(gradeGraceKey(grade), date);
        return value == null || value.isEmpty() ? null : Integer.valueOf(value);
    }

    /**
     * The day a claim's overdue count starts from: its due-by plus the grace days of its grade (the
     * one in force on its date) in force on its date, or its due-by when that grade has none. A
     * claim is overdue when this is before the sheet's today, and its late charge's 30-day
     * boundaries are counted from it.
     */
    public LocalDate overdueFrom(LocalDate dueBy, String grade, LocalDate date) {
        Integer grace = grade == null ? null : gradeGraceOn(grade, date);
        return grace == null ? dueBy : dueBy.plusDays(grace);
    }

    /** A sheet's floor until it is set. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** A sheet's terms until they are set. */
    public static final int DEFAULT_TERMS = 14;

    /** A sheet's late percent until it is set. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    /** The value of a key in force on a date: null when none is recorded on or before it, '' for none. */
    public String valueOn(String key, LocalDate date) {
        NavigableMap<LocalDate, String> values = dated.get(key);
        if (values == null || date == null) return null;
        Map.Entry<LocalDate, String> entry = values.floorEntry(date);
        return entry == null ? null : entry.getValue();
    }

    private BigDecimal figureOn(String key, LocalDate date) {
        String value = valueOn(key, date);
        return value == null || value.isEmpty() ? null : new BigDecimal(value).setScale(2);
    }

    /** The floor in force on a date. */
    public BigDecimal floorOn(LocalDate date) {
        BigDecimal floor = figureOn(FLOOR, date);
        return floor != null ? floor : DEFAULT_FLOOR;
    }

    /** The late percent in force on a date. */
    public BigDecimal latePctOn(LocalDate date) {
        BigDecimal pct = figureOn(LATE_PCT, date);
        return pct != null ? pct : DEFAULT_LATE_PCT;
    }

    /** The sheet's terms in force on a date. */
    public int termsOn(LocalDate date) {
        String value = valueOn(TERMS, date);
        return value == null || value.isEmpty() ? DEFAULT_TERMS : Integer.parseInt(value);
    }

    /** A grade's own terms in force on a date, or null when it takes the sheet's. */
    public Integer gradeTermsOn(String grade, LocalDate date) {
        String value = valueOn(gradeTermsKey(grade), date);
        return value == null || value.isEmpty() ? null : Integer.valueOf(value);
    }

    /** The terms of a person's claim made on a date (the sheet's today then): their own in force then, else their grade's then, else the sheet's. */
    public int termsFor(net.officefloor.hq.app.person.Person person, LocalDate date) {
        Integer own = person.termsOn(date);
        return own != null ? own : termsFor(person.gradeOn(date), date);
    }

    /** The terms of a grade on a date: its own, else the sheet's. */
    public int termsFor(String grade, LocalDate date) {
        Integer own = gradeTermsOn(grade, date);
        return own != null ? own : termsOn(date);
    }

    /** The key of a grade's own clerk limit. */
    public static String gradeClerkLimitKey(String grade) {
        return "clerk-limit-" + grade;
    }

    /** A grade's own clerk limit in force on a date, or null when it has none. */
    public BigDecimal gradeClerkLimitOn(String grade, LocalDate date) {
        return figureOn(gradeClerkLimitKey(grade), date);
    }

    /** The clerk limit of a grade in force on a date: the grade's own when it has one, else the sheet's (null: no limit). */
    public BigDecimal clerkLimitFor(String grade, LocalDate date) {
        BigDecimal own = grade == null ? null : gradeClerkLimitOn(grade, date);
        return own != null ? own : clerkLimitOn(date);
    }

    /** The clerk limit in force on a date (null: no limit). */
    public BigDecimal clerkLimitOn(LocalDate date) {
        return figureOn(CLERK_LIMIT, date);
    }

    /** The proof threshold in force on a date (null: none). */
    public BigDecimal proofThresholdOn(LocalDate date) {
        return figureOn(PROOF_THRESHOLD, date);
    }

    /**
     * The proof threshold of a claim of a grade dated {@code date}: the grade's own in force on that
     * date when it has one, else the sheet's (null: none).
     */
    public BigDecimal proofThresholdFor(String grade, LocalDate date) {
        BigDecimal own = grade == null ? null : gradeProofThresholdOn(grade, date);
        return own != null ? own : proofThresholdOn(date);
    }

    /**
     * Whether a claim of a grade dated {@code date} with a due (null: n/a) needs a proof before it is
     * settled or approved: its due is above its proof threshold and it has no proofs, or, while the
     * proof kinds are set, none of a kind they list. A due of n/a, or no threshold, needs none.
     */
    public boolean needsProof(BigDecimal due, String grade, LocalDate date, net.officefloor.hq.app.claim.Claim claim) {
        BigDecimal threshold = proofThresholdFor(grade, date);
        if (threshold == null || due == null || due.compareTo(threshold) <= 0) return false;
        if (claim.getProofs() == 0) return true;
        for (String kind : proofKindList()) {
            if (claim.proofsOf(kind) == 0) return true;
        }
        return false;
    }

    /** The note threshold in force on a date (null: none). */
    public BigDecimal noteThresholdOn(LocalDate date) {
        return figureOn(NOTE_THRESHOLD, date);
    }

    /**
     * Whether a claim dated {@code date} with a due (null: n/a) and a note needs a note before it is
     * opened: its due is above the note threshold in force on its date and its note is empty. A due
     * of n/a, or no threshold, needs none.
     */
    public boolean needsNote(BigDecimal due, LocalDate date, String note) {
        BigDecimal threshold = noteThresholdOn(date);
        return (note == null || note.isBlank()) && threshold != null && due != null && due.compareTo(threshold) > 0;
    }

    /** The review threshold in force on a date (null: none). */
    public BigDecimal reviewThresholdOn(LocalDate date) {
        return figureOn(REVIEW_THRESHOLD, date);
    }

    /**
     * Whether a claim dated {@code date} with a due (null: n/a) goes to REVIEW when it is opened:
     * its due is above the review threshold in force on its date. A due of n/a, or no threshold,
     * goes straight to OPEN.
     */
    public boolean needsReview(BigDecimal due, LocalDate date) {
        BigDecimal threshold = reviewThresholdOn(date);
        return threshold != null && due != null && due.compareTo(threshold) > 0;
    }

    /** The cap in force on a date (null: none). */
    public BigDecimal capOn(LocalDate date) {
        return figureOn(CAP, date);
    }

    /** The rounding mode in force on a date (null: none). */
    public RoundingMode roundingOn(LocalDate date) {
        String value = valueOn(ROUNDING, date);
        if (HALF_UP.equals(value)) return RoundingMode.HALF_UP;
        if (HALF_EVEN.equals(value)) return RoundingMode.HALF_EVEN;
        return null;
    }

    /**
     * How every figure of a claim that rounds by {@code date} is rounded: by the rounding mode in
     * force on that date when there is one, else half up before the policy date ({@code today} when
     * it is blank), half to even on or after it.
     */
    public RoundingMode rounding(LocalDate date, LocalDate today) {
        RoundingMode mode = roundingOn(date);
        if (mode != null) return mode;
        LocalDate policy = policyDate != null ? policyDate : today;
        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The date of a new claim left undated: the entry date while it is set, else the sheet's today. */
    public LocalDate entryDay(LocalDate today) {
        return entryDate != null ? entryDate : today;
    }

    /** Whether a period ending {@code to} is past its grace days on {@code today}: never while they are off. */
    public boolean pastGrace(LocalDate to, LocalDate today) {
        return graceDays != null && to.plusDays(graceDays).isBefore(today);
    }

    /** Whether a claim opened on {@code today} is numbered within its period. */
    public boolean numbersByPeriod(LocalDate today) {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /**
     * A person's due-total (null: n/a) held to the cap in force on {@code date}, the date of their latest claim
     * that counts (null: none, no cap), less their cut total (not below 0.00): the cap covers their due-total and
     * their cut total together. A due-total of n/a is not capped.
     */
    public BigDecimal capped(BigDecimal dueTotal, BigDecimal cutTotal, LocalDate date) {
        BigDecimal cap = capOn(date);
        if (cap == null || dueTotal == null) return dueTotal;
        BigDecimal room = cap.subtract(cutTotal).max(BigDecimal.ZERO).setScale(2);
        return dueTotal.compareTo(room) <= 0 ? dueTotal : room;
    }

    /**
     * Whether a due (null: n/a) of a claim of a grade is within the clerk limit in force on the claim's
     * {@code date}: the grade's own when it has one, else the sheet's. A due of n/a is within any limit.
     */
    public boolean withinClerkLimit(BigDecimal due, String grade, LocalDate date) {
        BigDecimal clerkLimit = clerkLimitFor(grade, date);
        return clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
    }
}

/**
 * A claim's status: DRAFT when made, then OPEN, then SETTLED; a clerk's settle above the clerk
 * limit makes it PENDING until a steward approves it (SETTLED) or rejects it (OPEN again). A DRAFT,
 * OPEN or PENDING claim may be VOID; a SETTLED one too, by a steward within 7 days of its settlement.
 * A claim whose due is above the review threshold in force on its date goes to REVIEW instead of OPEN when
 * it is opened, unnumbered and counting in no total, until a steward reviews it (OPEN); it
 * may be VOID too. A DRAFT may be DELETED (it counts nowhere), and restored to a DRAFT on the sheet's today it was deleted.
 */
export type ClaimStatus = 'DRAFT' | 'REVIEW' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';

/**
 * A claim: its amount with two decimals, its date (yyyy-MM-dd), its note, its status and its
 * number on the sheet (given when it is settled or approved; '' until then), and its due as
 * fixed when it was settled ('' while its due is live: unsettled, or settled with no rate), and
 * who opened it ('' until it is opened); whether its person's last statement bound it, and the
 * figure it was bound to ('' when not stated; n/a when it had none); and, for a correction (a
 * negative amount), the number of the settled claim it corrects ('' for any other claim); and the
 * date (yyyy-MM-dd) its figures round by (a correction's is the date of the claim it corrects).
 */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  openedBy: string;
  stated: boolean;
  statedDue: string;
  /** The late charge its person's last statement bound it to, with its figure ('' when none is bound: it follows the sheet's today). */
  statedLate: string;
  corrects: string;
  roundDate: string;
  /** Its due-by (yyyy-MM-dd), fixed when it was made: the terms-th business day after its date (skipping weekends and the sheet's holidays then), its terms its person's own, else its grade's then. */
  dueBy: string;
  /**
   * Its status log, oldest first: one line per status it has had, as
   * `<STATUS> by <user> on <date> due=<due>` (the sheet's today and its due at that moment).
   */
  log: string[];
  /** The date (yyyy-MM-dd) it is deferred until; '' when it was never deferred. */
  deferredUntil: string;
  /** How many proofs it has had added. */
  proofs: number;
  /** How many of its proofs are receipts. */
  proofReceipts: number;
  /** How many of its proofs are photos. */
  proofPhotos: number;
  /** The number of the claim it was split off; '' when it was not split off one. */
  splitFrom: string;
  /** The user whose open editor locks it on the sheet's today; '' when no one's does. */
  lockedBy: string;
  /** Whether it was added while its period was soft-closed. */
  lateEntry: boolean;
  /** The last sheet's today (yyyy-MM-dd) a reminder was written for it; '' when it was never reminded. */
  remindedOn: string;
  /** Whether a steward waived its late charge: it bears none from then on. */
  waived: boolean;
  /** Whether it is held: it still counts in every total; a hold only matters to pool cuts. */
  held: boolean;
  /** Its external reference, unique on the sheet regardless of case; '' when it has none. */
  ref: string;
  /** Its tags: trimmed, lower-cased, without repeats, sorted; empty when it has none. */
  tags: string[];
  /** The reason it was voided with, from the sheet's list; '' when none. */
  voidReason: string;
  /** Its comments, oldest first, as `<user> on <date>: <text>` (the sheet's today when written). */
  comments: string[];
  /** The number of the bulk settle batch that settled it; '' when none did (settled one at a time, or not settled). */
  batch: string;
  /** Its lines, oldest first, as `<label> <qty> x <unit>`; while it has any, its amount is their total. */
  lines: string[];
  /** The sheet's today (yyyy-MM-dd) when it went to REVIEW; '' when it never did. */
  reviewOn: string;
  /**
   * Its shares with other people on the sheet, oldest first: each holder's person id and their percent
   * (two decimals). A holder's part is its amount times their share / 100 times the rate of the holder's
   * own grade in force on its date / 100, rounded like the claim (none with no rate); a settled claim's parts
   * stay frozen at its due times their share / 100, rounded half to even. Its own person keeps the rest.
   */
  shares: ClaimShare[];
  /** The user a steward assigned it to review while in REVIEW; '' when none. Kept once it leaves REVIEW. */
  reviewUser: string;
  /** The sheet's today (yyyy-MM-dd) when it last went to PENDING; '' when it never did. */
  pendingOn: string;
};

/** A holder's share of a claim: their person id and their percent, two decimals. */
export type ClaimShare = { personId: string; share: string };

/** Whether a claim is a correction: it has no floor and no late charge. */
export const isCorrection = (c: Claim) => c.corrects !== '';

/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * Whether a claim is late pending: it is PENDING and its pending day plus the pending SLA in days
 * ('' for none: never late) is before the sheet's today.
 */
export function isPendingLate(c: Claim, today: string, pendingSla: string): boolean {
  if (c.status !== 'PENDING' || c.pendingOn === '' || pendingSla === '' || today === '') return false;
  const [y, m, d] = c.pendingOn.split('-').map(Number);
  const due = new Date(Date.UTC(y, m - 1, d + Number(pendingSla))).toISOString().slice(0, 10);
  return due < today;
}

/**
 * Whether a claim is late for review: it is in REVIEW and its review day plus the review SLA in days
 * ('' for none: never late) is before the sheet's today.
 */
export function isReviewLate(c: Claim, today: string, reviewSla: string): boolean {
  if (c.status !== 'REVIEW' || c.reviewOn === '' || reviewSla === '' || today === '') return false;
  const [y, m, d] = c.reviewOn.split('-').map(Number);
  const due = new Date(Date.UTC(y, m - 1, d + Number(reviewSla))).toISOString().slice(0, 10);
  return due < today;
}

/**
 * Whether a claim's stated figure is in force: its person's last statement bound it (OPEN or
 * PENDING alike).
 */
export const isBound = (c: Claim) => c.stated;

/**
 * Whether a claim is deferred on the sheet's `today`: not bound by a statement, and deferred until a
 * date after today. From that date on it is a claim like any other. While a statement binds it, its
 * deferral waits until the binding ends, and then takes effect whatever its status since (one settled
 * while bound drops out of the totals until that date too).
 */
export const isDeferred = (c: Claim, today: string) =>
  !isBound(c) && c.deferredUntil !== '' && today !== '' && today < c.deferredUntil;

/**
 * Whether the claim's row shows it deferred: it was deferred until a date after the sheet's
 * `today`, whatever its status since (a deferred claim voided stays shown deferred), and no
 * statement binds it. Only `isDeferred` decides what counts.
 */
export const showsDeferred = (c: Claim, today: string) =>
  !isBound(c) && c.deferredUntil !== '' && today !== '' && today < c.deferredUntil;

/**
 * Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED
 * do, and an OPEN or PENDING one not when dated within one of `holds` (a retired person's, see
 * `liveHolds`; a hold of its own or its person's does not take it out), unless a statement binds it;
 * never one deferred on `today`.
 */
export const counts = (c: Claim, holds: Hold[], today: string) =>
  !isDeferred(c, today) && (c.status === 'SETTLED' || (isOpen(c) && (isBound(c) || !heldOn(holds, c.date))));

/**
 * Whether a claim's amount counts toward claimed and the claimed-total: as `counts`, but a hold
 * (its own or its person's) does not take it out; only `holds` given (a retired person's) do.
 */
export const countsClaimed = (c: Claim, holds: Hold[], today: string) =>
  !isDeferred(c, today) && (c.status === 'SETTLED' || (isOpen(c) && (isBound(c) || !heldOn(holds, c.date))));

/**
 * A claim's status at the end of `day` (yyyy-MM-dd), as its log records it: the status of its last
 * line dated on or before it; null when it had none then (it was added after).
 */
export function statusOn(c: Claim, day: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of c.log) {
    const m = /^(\w+) by .* on (\d{4}-\d{2}-\d{2}) due=\S*$/.exec(line);
    if (m && m[2] <= day) status = m[1] as ClaimStatus;
  }
  return status;
}

/**
 * Whether a claim counted at the end of `day`: as `counts`, with the status its log records then
 * (never when it was added after), its statement binding and deferral as they are on `today`.
 */
export const countedOn = (c: Claim, day: string, holds: Hold[], today: string) => {
  const status = statusOn(c, day);
  if (status === null || isDeferred(c, today)) return false;
  return status === 'SETTLED' || ((status === 'OPEN' || status === 'PENDING') && (isBound(c) || !heldOn(holds, c.date)));
};

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

export const claimsQuery = (sheetId: string) => ({
  queryKey: claimsKey(sheetId),
  queryFn: async () =>
    (await getJson<{ claims: Claim[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).claims,
});

export const tagsKey = (sheetId: string) => [...claimsKey(sheetId), 'tags'] as const;

/** Every tag ever used on the sheet, sorted (re-read whenever its claims are). */
export function useTagsUsed(sheetId: string) {
  return useQuery({
    queryKey: tagsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ tags: string[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).tags,
  });
}

export const lastBatchKey = (sheetId: string) => [...claimsKey(sheetId), 'last-batch'] as const;

/** The number of the sheet's last bulk settle batch; '' when there has been none (re-read whenever its claims are). */
export function useLastBatch(sheetId: string) {
  return useQuery({
    queryKey: lastBatchKey(sheetId),
    queryFn: async () =>
      (await getJson<{ lastBatch: string }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).lastBatch,
  });
}

/** The sheet's claims, newest first. */
export function useClaims(sheetId: string) {
  return useQuery(claimsQuery(sheetId));
}

