162	     * boundaries are counted from it.
163	     */
164	    public LocalDate overdueFrom(LocalDate dueBy, String grade, LocalDate date) {
165	        Integer grace = grade == null ? null : gradeGraceOn(grade, date);
166	        return grace == null ? dueBy : dueBy.plusDays(grace);
167	    }
168	
169	    /** A sheet's floor until it is set. */
170	    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");
171	
172	    /** A sheet's terms until they are set. */
173	    public static final int DEFAULT_TERMS = 14;
174	
175	    /** A sheet's late percent until it is set. */
176	    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");
177	
178	    /** The value of a key in force on a date: null when none is recorded on or before it, '' for none. */
179	    public String valueOn(String key, LocalDate date) {
180	        NavigableMap<LocalDate, String> values = dated.get(key);
181	        if (values == null || date == null) return null;
182	        Map.Entry<LocalDate, String> entry = values.floorEntry(date);
183	        return entry == null ? null : entry.getValue();
184	    }
185	
186	    private BigDecimal figureOn(String key, LocalDate date) {
187	        String value = valueOn(key, date);
188	        return value == null || value.isEmpty() ? null : new BigDecimal(value).setScale(2);
189	    }
190	
191	    /** The floor in force on a date. */
192	    public BigDecimal floorOn(LocalDate date) {
193	        BigDecimal floor = figureOn(FLOOR, date);
194	        return floor != null ? floor : DEFAULT_FLOOR;
195	    }
196	
197	    /** The late percent in force on a date. */
198	    public BigDecimal latePctOn(LocalDate date) {
199	        BigDecimal pct = figureOn(LATE_PCT, date);
200	        return pct != null ? pct : DEFAULT_LATE_PCT;
201	    }
202	
203	    /** The sheet's terms in force on a date. */
204	    public int termsOn(LocalDate date) {
205	        String value = valueOn(TERMS, date);
206	        return value == null || value.isEmpty() ? DEFAULT_TERMS : Integer.parseInt(value);
207	    }
208	
209	    /** A grade's own terms in force on a date, or null when it takes the sheet's. */
210	    public Integer gradeTermsOn(String grade, LocalDate date) {
211	        String value = valueOn(gradeTermsKey(grade), date);
212	        return value == null || value.isEmpty() ? null : Integer.valueOf(value);
213	    }
214	
215	    /** The terms of a person's claim made on a date (the sheet's today then): their own in force then, else their grade's then, else the sheet's. */
216	    public int termsFor(net.officefloor.hq.app.person.Person person, LocalDate date) {
217	        Integer own = person.termsOn(date);
218	        return own != null ? own : termsFor(person.gradeOn(date), date);
219	    }
220	
221	    /** The terms of a grade on a date: its own, else the sheet's. */
222	    public int termsFor(String grade, LocalDate date) {
223	        Integer own = gradeTermsOn(grade, date);
224	        return own != null ? own : termsOn(date);
225	    }
226	
227	    /** The key of a grade's own clerk limit. */
228	    public static String gradeClerkLimitKey(String grade) {
229	        return "clerk-limit-" + grade;
230	    }
231	
232	    /** A grade's own clerk limit in force on a date, or null when it has none. */
233	    public BigDecimal gradeClerkLimitOn(String grade, LocalDate date) {
234	        return figureOn(gradeClerkLimitKey(grade), date);
235	    }
236	
237	    /** The clerk limit of a grade in force on a date: the grade's own when it has one, else the sheet's (null: no limit). */
238	    public BigDecimal clerkLimitFor(String grade, LocalDate date) {
239	        BigDecimal own = grade == null ? null : gradeClerkLimitOn(grade, date);
240	        return own != null ? own : clerkLimitOn(date);
241	    }
242	
243	    /** The clerk limit in force on a date (null: no limit). */
244	    public BigDecimal clerkLimitOn(LocalDate date) {
245	        return figureOn(CLERK_LIMIT, date);
246	    }
247	
248	    /** The proof threshold in force on a date (null: none). */
249	    public BigDecimal proofThresholdOn(LocalDate date) {
250	        return figureOn(PROOF_THRESHOLD, date);
251	    }
252	
253	    /**
254	     * The proof threshold of a claim of a grade dated {@code date}: the grade's own in force on that
255	     * date when it has one, else the sheet's (null: none).
256	     */
257	    public BigDecimal proofThresholdFor(String grade, LocalDate date) {
258	        BigDecimal own = grade == null ? null : gradeProofThresholdOn(grade, date);
259	        return own != null ? own : proofThresholdOn(date);
260	    }
261	
262	    /**
263	     * Whether a claim of a grade dated {@code date} with a due (null: n/a) needs a proof before it is
264	     * settled or approved: its due is above its proof threshold and it has no proofs, or, while the
265	     * proof kinds are set, none of a kind they list. A due of n/a, or no threshold, needs none.
266	     */
267	    public boolean needsProof(BigDecimal due, String grade, LocalDate date, net.officefloor.hq.app.claim.Claim claim) {
268	        BigDecimal threshold = proofThresholdFor(grade, date);
269	        if (threshold == null || due == null || due.compareTo(threshold) <= 0) return false;
270	        if (claim.getProofs() == 0) return true;
271	        for (String kind : proofKindList()) {
272	            if (claim.proofsOf(kind) == 0) return true;
273	        }
274	        return false;
275	    }
276	
277	    /** The note threshold in force on a date (null: none). */
278	    public BigDecimal noteThresholdOn(LocalDate date) {
279	        return figureOn(NOTE_THRESHOLD, date);
280	    }
281	
282	    /**
283	     * Whether a claim dated {@code date} with a due (null: n/a) and a note needs a note before it is
284	     * opened: its due is above the note threshold in force on its date and its note is empty. A due
285	     * of n/a, or no threshold, needs none.
286	     */
287	    public boolean needsNote(BigDecimal due, LocalDate date, String note) {
288	        BigDecimal threshold = noteThresholdOn(date);
289	        return (note == null || note.isBlank()) && threshold != null && due != null && due.compareTo(threshold) > 0;
290	    }
291	
292	    /** The review threshold in force on a date (null: none). */
293	    public BigDecimal reviewThresholdOn(LocalDate date) {
294	        return figureOn(REVIEW_THRESHOLD, date);
295	    }
296	
297	    /**
298	     * Whether a claim dated {@code date} with a due (null: n/a) goes to REVIEW when it is opened:
299	     * its due is above the review threshold in force on its date. A due of n/a, or no threshold,
300	     * goes straight to OPEN.
301	     */
302	    public boolean needsReview(BigDecimal due, LocalDate date) {
303	        BigDecimal threshold = reviewThresholdOn(date);
304	        return threshold != null && due != null && due.compareTo(threshold) > 0;
305	    }
306	
307	    /** The cap in force on a date (null: none). */
308	    public BigDecimal capOn(LocalDate date) {
309	        return figureOn(CAP, date);
310	    }
311	
312	    /** The rounding mode in force on a date (null: none). */
313	    public RoundingMode roundingOn(LocalDate date) {
314	        String value = valueOn(ROUNDING, date);
315	        if (HALF_UP.equals(value)) return RoundingMode.HALF_UP;
316	        if (HALF_EVEN.equals(value)) return RoundingMode.HALF_EVEN;
317	        return null;
318	    }
319	
320	    /**
321	     * How every figure of a claim that rounds by {@code date} is rounded: by the rounding mode in
322	     * force on that date when there is one, else half up before the policy date ({@code today} when
323	     * it is blank), half to even on or after it.
324	     */
325	    public RoundingMode rounding(LocalDate date, LocalDate today) {
326	        RoundingMode mode = roundingOn(date);
327	        if (mode != null) return mode;
328	        LocalDate policy = policyDate != null ? policyDate : today;
329	        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
330	    }
331	
332	    /** The date of a new claim left undated: the entry date while it is set, else the sheet's today. */
333	    public LocalDate entryDay(LocalDate today) {
334	        return entryDate != null ? entryDate : today;
335	    }
336	
337	    /** Whether a period ending {@code to} is past its grace days on {@code today}: never while they are off. */
338	    public boolean pastGrace(LocalDate to, LocalDate today) {
339	        return graceDays != null && to.plusDays(graceDays).isBefore(today);
340	    }
341	
342	    /** Whether a claim opened on {@code today} is numbered within its period. */
343	    public boolean numbersByPeriod(LocalDate today) {
344	        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
345	    }
346	
347	    /**
348	     * A person's due-total (null: n/a) held to the cap in force on {@code date}, the date of their latest claim
349	     * that counts (null: none, no cap), less their cut total (not below 0.00): the cap covers their due-total and
350	     * their cut total together. A due-total of n/a is not capped.
351	     */
352	    public BigDecimal capped(BigDecimal dueTotal, BigDecimal cutTotal, LocalDate date) {
353	        BigDecimal cap = capOn(date);
354	        if (cap == null || dueTotal == null) return dueTotal;
355	        BigDecimal room = cap.subtract(cutTotal).max(BigDecimal.ZERO).setScale(2);
356	        return dueTotal.compareTo(room) <= 0 ? dueTotal : room;
357	    }
358	
359	    /**
360	     * Whether a due (null: n/a) of a claim of a grade is within the clerk limit in force on the claim's
361	     * {@code date}: the grade's own when it has one, else the sheet's. A due of n/a is within any limit.
362	     */
363	    public boolean withinClerkLimit(BigDecimal due, String grade, LocalDate date) {
364	        BigDecimal clerkLimit = clerkLimitFor(grade, date);
365	        return clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
366	    }
367	}
368	
369	/**
370	 * A claim's status: DRAFT when made, then OPEN, then SETTLED; a clerk's settle above the clerk
371	 * limit makes it PENDING until a steward approves it (SETTLED) or rejects it (OPEN again). A DRAFT,
372	 * OPEN or PENDING claim may be VOID; a SETTLED one too, by a steward within 7 days of its settlement.
373	 * A claim whose due is above the review threshold in force on its date goes to REVIEW instead of OPEN when
374	 * it is opened, unnumbered and counting in no total, until a steward reviews it (OPEN); it
375	 * may be VOID too. A DRAFT may be DELETED (it counts nowhere), and restored to a DRAFT on the sheet's today it was deleted.
376	 */
377	export type ClaimStatus = 'DRAFT' | 'REVIEW' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';
378	
379	/**
380	 * A claim: its amount with two decimals, its date (yyyy-MM-dd), its note, its status and its
381	 * number on the sheet (given when it is settled or approved; '' until then), and its due as
382	 * fixed when it was settled ('' while its due is live: unsettled, or settled with no rate), and
383	 * who opened it ('' until it is opened); whether its person's last statement bound it, and the
384	 * figure it was bound to ('' when not stated; n/a when it had none); and, for a correction (a
385	 * negative amount), the number of the settled claim it corrects ('' for any other claim); and the
386	 * date (yyyy-MM-dd) its figures round by (a correction's is the date of the claim it corrects).
387	 */
388	export type Claim = {
389	  id: string;
390	  personId: string;
391	  amount: string;
392	  date: string;
393	  note: string;
394	  status: ClaimStatus;
395	  number: string;
396	  due: string;
397	  openedBy: string;
398	  stated: boolean;
399	  statedDue: string;
400	  /** The late charge its person's last statement bound it to, with its figure ('' when none is bound: it follows the sheet's today). */
401	  statedLate: string;
402	  corrects: string;
403	  roundDate: string;
404	  /** Its due-by (yyyy-MM-dd), fixed when it was made: the terms-th business day after its date (skipping weekends and the sheet's holidays then), its terms its person's own, else its grade's then. */
405	  dueBy: string;
406	  /**
407	   * Its status log, oldest first: one line per status it has had, as
408	   * `<STATUS> by <user> on <date> due=<due>` (the sheet's today and its due at that moment).
409	   */
410	  log: string[];
411	  /** The date (yyyy-MM-dd) it is deferred until; '' when it was never deferred. */
412	  deferredUntil: string;
413	  /** How many proofs it has had added. */
414	  proofs: number;
415	  /** How many of its proofs are receipts. */
416	  proofReceipts: number;
417	  /** How many of its proofs are photos. */
418	  proofPhotos: number;
419	  /** The number of the claim it was split off; '' when it was not split off one. */
420	  splitFrom: string;
421	  /** The user whose open editor locks it on the sheet's today; '' when no one's does. */
422	  lockedBy: string;
423	  /** Whether it was added while its period was soft-closed. */
424	  lateEntry: boolean;
425	  /** The last sheet's today (yyyy-MM-dd) a reminder was written for it; '' when it was never reminded. */
426	  remindedOn: string;
427	  /** Whether a steward waived its late charge: it bears none from then on. */
428	  waived: boolean;
429	  /** Whether it is held: it still counts in every total; a hold only matters to pool cuts. */
430	  held: boolean;
431	  /** Its external reference, unique on the sheet regardless of case; '' when it has none. */
432	  ref: string;
433	  /** Its tags: trimmed, lower-cased, without repeats, sorted; empty when it has none. */
434	  tags: string[];
435	  /** The reason it was voided with, from the sheet's list; '' when none. */
436	  voidReason: string;
437	  /** Its comments, oldest first, as `<user> on <date>: <text>` (the sheet's today when written). */
438	  comments: string[];
439	  /** The number of the bulk settle batch that settled it; '' when none did (settled one at a time, or not settled). */
440	  batch: string;
441	  /** Its lines, oldest first, as `<label> <qty> x <unit>`; while it has any, its amount is their total. */
442	  lines: string[];
443	  /** The sheet's today (yyyy-MM-dd) when it went to REVIEW; '' when it never did. */
444	  reviewOn: string;
445	  /**
446	   * Its shares with other people on the sheet, oldest first: each holder's person id and their percent
447	   * (two decimals). A holder's part is its amount times their share / 100 times the rate of the holder's
448	   * own grade in force on its date / 100, rounded like the claim (none with no rate); a settled claim's parts
449	   * stay frozen at its due times their share / 100, rounded half to even. Its own person keeps the rest.
450	   */
451	  shares: ClaimShare[];
452	  /** The user a steward assigned it to review while in REVIEW; '' when none. Kept once it leaves REVIEW. */
453	  reviewUser: string;
454	  /** The sheet's today (yyyy-MM-dd) when it last went to PENDING; '' when it never did. */
455	  pendingOn: string;
456	};
457	
458	/** A holder's share of a claim: their person id and their percent, two decimals. */
459	export type ClaimShare = { personId: string; share: string };
460	
461	/** Whether a claim is a correction: it has no floor and no late charge. */
462	export const isCorrection = (c: Claim) => c.corrects !== '';
463	
464	/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
465	export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';
466	
467	/**
468	 * Whether a claim is late pending: it is PENDING and its pending day plus the pending SLA in days
469	 * ('' for none: never late) is before the sheet's today.
470	 */
471	export function isPendingLate(c: Claim, today: string, pendingSla: string): boolean {
472	  if (c.status !== 'PENDING' || c.pendingOn === '' || pendingSla === '' || today === '') return false;
473	  const [y, m, d] = c.pendingOn.split('-').map(Number);
474	  const due = new Date(Date.UTC(y, m - 1, d + Number(pendingSla))).toISOString().slice(0, 10);
475	  return due < today;
476	}
477	
478	/**
479	 * Whether a claim is late for review: it is in REVIEW and its review day plus the review SLA in days
480	 * ('' for none: never late) is before the sheet's today.
481	 */
482	export function isReviewLate(c: Claim, today: string, reviewSla: string): boolean {
483	  if (c.status !== 'REVIEW' || c.reviewOn === '' || reviewSla === '' || today === '') return false;
484	  const [y, m, d] = c.reviewOn.split('-').map(Number);
485	  const due = new Date(Date.UTC(y, m - 1, d + Number(reviewSla))).toISOString().slice(0, 10);
486	  return due < today;
487	}
488	
489	/**
490	 * Whether a claim's stated figure is in force: its person's last statement bound it (OPEN or
491	 * PENDING alike).
492	 */
493	export const isBound = (c: Claim) => c.stated;
494	
495	/**
496	 * Whether a claim is deferred on the sheet's `today`: not bound by a statement, and deferred until a
497	 * date after today. From that date on it is a claim like any other. While a statement binds it, its
498	 * deferral waits until the binding ends, and then takes effect whatever its status since (one settled
499	 * while bound drops out of the totals until that date too).
500	 */
501	export const isDeferred = (c: Claim, today: string) =>
502	  !isBound(c) && c.deferredUntil !== '' && today !== '' && today < c.deferredUntil;
503	
504	/**
505	 * Whether the claim's row shows it deferred: it was deferred until a date after the sheet's
506	 * `today`, whatever its status since (a deferred claim voided stays shown deferred), and no
507	 * statement binds it. Only `isDeferred` decides what counts.
508	 */
509	export const showsDeferred = (c: Claim, today: string) =>
510	  !isBound(c) && c.deferredUntil !== '' && today !== '' && today < c.deferredUntil;
511	
512	/**
513	 * Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED
514	 * do, and an OPEN or PENDING one not when dated within one of `holds` (a retired person's, see
515	 * `liveHolds`; a hold of its own or its person's does not take it out), unless a statement binds it;
516	 * never one deferred on `today`.
517	 */
518	export const counts = (c: Claim, holds: Hold[], today: string) =>
519	  !isDeferred(c, today) && (c.status === 'SETTLED' || (isOpen(c) && (isBound(c) || !heldOn(holds, c.date))));
520	
521	/**
522	 * Whether a claim's amount counts toward claimed and the claimed-total: as `counts`, but a hold
523	 * (its own or its person's) does not take it out; only `holds` given (a retired person's) do.
524	 */
525	export const countsClaimed = (c: Claim, holds: Hold[], today: string) =>
526	  !isDeferred(c, today) && (c.status === 'SETTLED' || (isOpen(c) && (isBound(c) || !heldOn(holds, c.date))));
527	
528	/**
529	 * A claim's status at the end of `day` (yyyy-MM-dd), as its log records it: the status of its last
530	 * line dated on or before it; null when it had none then (it was added after).
531	 */
532	export function statusOn(c: Claim, day: string): ClaimStatus | null {
533	  let status: ClaimStatus | null = null;
534	  for (const line of c.log) {
535	    const m = /^(\w+) by .* on (\d{4}-\d{2}-\d{2}) due=\S*$/.exec(line);
536	    if (m && m[2] <= day) status = m[1] as ClaimStatus;
537	  }
538	  return status;
539	}
540	
541	/**
542	 * Whether a claim counted at the end of `day`: as `counts`, with the status its log records then
543	 * (never when it was added after), its statement binding and deferral as they are on `today`.
544	 */
545	export const countedOn = (c: Claim, day: string, holds: Hold[], today: string) => {
546	  const status = statusOn(c, day);
547	  if (status === null || isDeferred(c, today)) return false;
548	  return status === 'SETTLED' || ((status === 'OPEN' || status === 'PENDING') && (isBound(c) || !heldOn(holds, c.date)));
549	};
550	
551	export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;
552	
553	export const claimsQuery = (sheetId: string) => ({
554	  queryKey: claimsKey(sheetId),
555	  queryFn: async () =>
556	    (await getJson<{ claims: Claim[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).claims,
557	});
558	
559	export const tagsKey = (sheetId: string) => [...claimsKey(sheetId), 'tags'] as const;
560	
561	/** Every tag ever used on the sheet, sorted (re-read whenever its claims are). */
562	export function useTagsUsed(sheetId: string) {
563	  return useQuery({
564	    queryKey: tagsKey(sheetId),
565	    queryFn: async () =>
566	      (await getJson<{ tags: string[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).tags,
567	  });
568	}
569	
570	export const lastBatchKey = (sheetId: string) => [...claimsKey(sheetId), 'last-batch'] as const;
571	
572	/** The number of the sheet's last bulk settle batch; '' when there has been none (re-read whenever its claims are). */
573	export function useLastBatch(sheetId: string) {
574	  return useQuery({
575	    queryKey: lastBatchKey(sheetId),
576	    queryFn: async () =>
577	      (await getJson<{ lastBatch: string }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).lastBatch,
578	  });
579	}
580	
581	/** The sheet's claims, newest first. */
582	export function useClaims(sheetId: string) {
583	  return useQuery(claimsQuery(sheetId));
584	}
585	
586	/** An amount as a claim takes it: 0.00 or more, with up to two decimals. */
587	export const AMOUNT = /^\d+(\.\d{1,2})?$/;
588	
589	/** An amount as the claim form takes it: up to two decimals, negative for a correction. */
590	export const CLAIM_AMOUNT = /^-?\d+(\.\d{1,2})?$/;
591	
592	/**
593	 * A claim number, as a correction names the claim it corrects: a sheet-wide number (one given
594	 * before numbering restarted each fiscal year), a number within a fiscal year (<FY>-<n>), or a number
595	 * within a period (<period name>-<n>, X-<n> for a claim in no period).
596	 */
597	export const CLAIM_NUMBER = /^(\d+|.+-\d+)$/;
598	
599	/**
600	 * The amounts of the claims that count (OPEN, PENDING and SETTLED, held or not, but not unbound open ones of a
601	 * retired person: `holds` tells by person id (see `retiredHolds`), nor ones deferred on `today`), leaving out corrections, added up, in whole cents so no rounding creeps in, shown with two
602	 * decimals.
603	 */
604	export function sumAmounts(claims: Claim[], holds: (personId: string) => Hold[], today: string): string {
605	  const cents = claims.filter((c) => !isCorrection(c) && countsClaimed(c, holds(c.personId), today)).reduce((n, c) => n + Math.round(Number(c.amount) * 100), 0);
606	  return (cents / 100).toFixed(2);
607	}
608

