386	/**
387	 * A claim's status. It starts as DRAFT, is opened (OPEN) and then settled (SETTLED). A clerk's
388	 * settle above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED) or
389	 * rejects it (back to OPEN). A claim whose due is above the review threshold in force on its date goes
390	 * to REVIEW instead of OPEN when it is opened, until a steward reviews it (OPEN). A claim is numbered only when it is SETTLED.
391	 * A DRAFT, REVIEW, OPEN or PENDING claim can be voided (VOID); a SETTLED one
392	 * too, by a steward within days of its settlement ({@link VoidClaim}). VOID is final. A DRAFT claim can be deleted
393	 * (DELETED), and made a DRAFT again by a restore on the sheet's today it was deleted ({@link RestoreClaim}). Only OPEN, PENDING and SETTLED claims count toward any total.
394	 */
395	public enum ClaimStatus {
396	    DRAFT(null), REVIEW("CLAIM_REVIEW"), OPEN("CLAIM_OPENED"), PENDING("CLAIM_PENDING"), SETTLED("CLAIM_SETTLED"), VOID("CLAIM_VOIDED"),
397	    DELETED("CLAIM_DELETED");
398	
399	    private final String auditEvent;
400	
401	    ClaimStatus(String auditEvent) {
402	        this.auditEvent = auditEvent;
403	    }
404	
405	    /** The audit event written when a claim moves into this status. */
406	    public String auditEvent() {
407	        return auditEvent;
408	    }
409	
410	    /** Whether a claim in this status may move to {@code next}. */
411	    public boolean canMoveTo(ClaimStatus next) {
412	        return switch (next) {
413	            case REVIEW -> this == DRAFT;
414	            case OPEN -> this == DRAFT || this == REVIEW;
415	            case PENDING -> this == OPEN;
416	            case SETTLED -> this == OPEN;
417	            case VOID -> this == DRAFT || this == REVIEW || this == OPEN || this == PENDING || this == SETTLED;
418	            case DELETED -> this == DRAFT;
419	            case DRAFT -> this == DELETED;
420	        };
421	    }
