    41	            settle(sheet, claim, Audit.user(request), people, rates, roles, settingsStore);
    42	        } else {
    43	            if (on.isAfter(sheet.today())) {
    44	                throw new InvalidClaimStatusException("A claim is settled as of a date on or before today");
    45	            }
