    90	    /** As above; with {@code fixed} (a one-element holder) the due is the one it holds instead of today's. */
    91	    private static void settle(Sheet sheet, Claim claim, String user, PersonRepository people, RateRepository rates,
    92	            RoleRepository roles, SettingsRepository settingsStore, boolean judged, BigDecimal[] fixed)
    93	            throws InvalidClaimStatusException, SelfSettleException {
    94	        Person person = people.find(sheet.id(), claim.getPersonId());
    95	        Settings settings = settingsStore.find(sheet.id());
    96	        String role = roles.roleOf(sheet.id(), user);
    97	        if (!settings.allows("settle", role)) {
    98	            throw new InvalidClaimStatusException("A " + role + " may not settle a claim");
    99	        }
   100	        String grade = person.gradeOn(claim.getDate());
   101	        BigDecimal figure = ClaimFigure.of(claim, rates.findAll(sheet.id()), grade, settings, sheet.today());
   102	        // The late charge is read while the claim is still OPEN.
   103	        BigDecimal late = ClaimFigure.late(claim, figure, grade, settings, sheet.today());
   104	        if (claim.isDeferredOn(sheet.today())) {
   105	            throw new InvalidClaimStatusException("A claim deferred until " + claim.getDeferredUntil() + " cannot be settled");
   106	        }
   107	        if (!claim.getStatus().canMoveTo(ClaimStatus.SETTLED)) {
   108	            throw new InvalidClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
   109	        }
   110	        BigDecimal due = fixed != null ? fixed[0] : ClaimFigure.due(figure, late);
