   112	        if (!settings.withinClerkLimit(due, grade, claim.getDate()) && (Role.CLERK.equals(role) || Role.RESTRICTED.equals(role))) {
   113	            claim.moveTo(ClaimStatus.PENDING);
   114	            return;
   115	        }
   116	        claim.moveTo(ClaimStatus.SETTLED);
   117	        claim.setSettledDue(due);
