   122	     * and a claim whose due is above the proof threshold without the proofs it needs.
   123	     */
   124	    static void judge(Claim claim, String user, BigDecimal due, String grade, Settings settings)
   125	            throws InvalidClaimStatusException, SelfSettleException {
   126	        if (user.equals(claim.getOpenedBy())) throw new SelfSettleException(user);
   127	        if (claim.isOwnedBy(user)) throw new SelfSettleException(user, "last edited");
   128	        if (settings.needsProof(due, grade, claim.getDate(), claim)) throw new InvalidClaimStatusException(ProofRequired.MESSAGE);
   129	    }
