   132	    static BigDecimal dueNow(Sheet sheet, Claim claim, String grade, RateRepository rates, Settings settings) {
   133	        BigDecimal figure = ClaimFigure.of(claim, rates.findAll(sheet.id()), grade, settings, sheet.today());
   134	        return ClaimFigure.due(figure, ClaimFigure.late(claim, figure, grade, settings, sheet.today()));
