    34	            throw new ApprovalException("A claim cannot be approved by " + user + ", who opened it");
    35	        }
    36	        if (claim.isOwnedBy(user)) {
    37	            throw new ApprovalException("A claim cannot be approved by " + user + ", who last edited it");
    38	        }
