557	   322	     * Swap the person with the one next to them in the sheet's list: above ({@code up}) or below.
558	   323	     * Returns their new position, counting from 1; null when there is no one there (the top row
559	   324	     * cannot move up nor the bottom row down) and nothing is written.
560	   325	     */
561	   326	    public Integer move(Person person, boolean up) {
562	   327	        List<long[]> list = jdbc.query("SELECT id, list_pos FROM person WHERE sheet_id = ? AND merged_into IS NULL"
563	   328	                + " ORDER BY list_pos, id", (rs, n) -> new long[] { rs.getLong("id"), rs.getLong("list_pos") },
564	   329	                person.getSheetId());
565	   330	        int at = -1;
566	   331	        for (int i = 0; i < list.size(); i++) if (list.get(i)[0] == person.getId()) at = i;
567	   332	        int to = up ? at - 1 : at + 1;
568	   333	        if (at < 0 || to < 0 || to >= list.size()) return null;
569	   334	        long[] mine = list.get(at), theirs = list.get(to);
570	   335	        // Positions may tie (never in practice): give them distinct ones in the order listed.
571	   336	        long minePos = mine[1], theirsPos = theirs[1];
572	   337	        if (minePos == theirsPos) {
573	   338	            for (int i = 0; i < list.size(); i++) {
574	   339	                jdbc.update("UPDATE person SET list_pos = ? WHERE id = ?", i + 1L, list.get(i)[0]);
575	   340	            }
576	   341	            minePos = at + 1L;
577	   342	            theirsPos = to + 1L;
578	   343	        }
579	   344	        jdbc.update("UPDATE person SET list_pos = ? WHERE id = ?", theirsPos, mine[0]);
580	   345	        jdbc.update("UPDATE person SET list_pos = ? WHERE id = ?", minePos, theirs[0]);
581	   346	        return to + 1;
582	   347	    }
