612	   377	                    moved, sheetId, into.getId());
613	   378	            jdbc.update("UPDATE person_statement SET seq = -seq WHERE sheet_id = ? AND person_id = ? AND seq < 0",
614	   379	                    sheetId, into.getId());
615	   380	            jdbc.update("UPDATE person_statement SET person_id = ? WHERE sheet_id = ? AND person_id = ?",
616	   381	                    into.getId(), sheetId, from.getId());
617	   382	            if (into.getStatementCount() > 0) {
