637	   402	        // Those naming them name the other instead: not the other themselves, nor anyone already naming the other.
638	   403	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND patron_id = ? AND (person_id = ?"
639	   404	                + " OR person_id IN (SELECT p.person_id FROM person_patron p WHERE p.patron_id = ?))",
640	   405	                sheetId, from.getId(), into.getId(), into.getId());
641	   406	        jdbc.update("UPDATE person_patron SET patron_id = ? WHERE sheet_id = ? AND patron_id = ?",
