    24	            RoleRepository roles, SettingsRepository settingsStore, HttpServletRequest request,
    25	            Out<Resettlement> resettlement) throws InvalidClaimStatusException, ResettleException {
    26	        if (claim.getStatus() != ClaimStatus.SETTLED) {
    27	            throw new InvalidClaimStatusException("Only a SETTLED claim can be re-settled: this one is " + claim.getStatus());
    28	        }
    29	        String user = Audit.user(request);
    30	        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), user))) {
    31	            throw new ResettleException("Only a steward may re-settle a claim: " + user + " is a clerk");
    32	        }
