     9	/**
    10	 * A correction must name, by number, a SETTLED claim of the same person; any other claim names
    11	 * none. Nor may it exceed what remains of that claim: its amount less the corrections already made
    12	 * against it (VOID or DELETED ones left out).
    13	 */
    14	public class CheckCorrection {
    15	    public void check(@Val Claim claim, ClaimRepository repository) throws InvalidClaimException {
    16	        String corrects = claim.getCorrects();
    17	        if (corrects == null) return;
    18	        List<Claim> claims = repository.findByPerson(claim.getSheetId(), claim.getPersonId());
    19	        Claim corrected = claims.stream()
    20	                .filter((c) -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED)
    21	                .findFirst().orElse(null);
    22	        if (corrected == null) {
    23	            throw new InvalidClaimException("A correction names a settled claim of the same person");
    24	        }
    25	        // What remains: the target's amount plus the (negative) corrections already made against it.
    26	        BigDecimal remaining = corrected.getAmount();
    27	        for (Claim other : claims) {
    28	            if (claim.getId() != null && Objects.equals(claim.getId(), other.getId())) continue;
    29	            if (!corrects.equals(other.getCorrects())) continue;
    30	            if (other.getStatus() == ClaimStatus.VOID || other.getStatus() == ClaimStatus.DELETED) continue;
    31	            remaining = remaining.add(other.getAmount());
    32	        }
    33	        if (claim.getAmount().negate().compareTo(remaining) > 0) {
    34	            throw new InvalidClaimException("A correction may not exceed what remains of the claim it corrects");
    35	        }
    36	        // A correction rounds by the date of the claim it corrects.
    37	        claim.setCorrectedDate(corrected.getDate());
    38	    }
    39	}
