141	    21	        boolean kept = request.gradeFrom().isEmpty() && request.grade().equals(person.gradeOn(sheet.today()));
142	    22	        if (!kept && grades.isRetired(sheet.id(), request.grade())) throw RetiredGrades.refused(request.grade());
143	    23	        person.setName(request.name());
