146	    26	        termsEdit.set(new TermsEdit(!termsShown));
147	    27	        if (!request.termsFrom().isEmpty()) person.setTermsFrom(terms, LocalDate.parse(request.termsFrom()));
148	    28	        else if (!termsShown) person.setTerms(terms);
149	    29	        String contact = request.contactValue();
150	    30	        contactEdit.set(new ContactEdit(!java.util.Objects.equals(contact, person.getContact())));
151	    31	        person.setContact(contact);
