    14	public record ClaimInput(BigDecimal amount, LocalDate date, String note, String corrects, String ref, String tags) {
    15	    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,15}(\\.\\d{1,2})?");
    16	    private static final Pattern NUMBER = Pattern.compile("\\d{1,9}|.{1,190}-\\d{1,9}");
