    27	 * Settles the selected claims in list order (people by their position in the list, each person's
    28	 * claims newest first) by exactly the rules of settling one claim, as the signed-in user. A claim
    29	 * sent to PENDING counts as settled. It is all or nothing: if any selected claim cannot be settled (its
    30	 * status does not allow it, dated inside a closed period, opened or last edited by this user, not on
    31	 * the sheet), none is settled, every one counts as refused and nothing is written. Otherwise the
    32	 * claims form a batch, numbered on the sheet, and after their own lines a BATCH_SETTLED line gives
    33	 * the batch, its count and the frozen figures of those SETTLED added up.
    34	 * Each claim settled is logged and audited as a single settle is: its status line, then the
    35	 * watchers it notifies (once settled), then the figures it moved. A viewer, or anyone on an archived
    36	 * sheet, settles none: every selected claim is refused.
    37	 */
    38	public class SettleSelectedClaims {
    39	    public void settle(@Val Sheet sheet, @Val BulkSettleRequest request, ClaimRepository claims,
    40	            PersonRepository people, PeriodRepository periods, SheetRepository sheets, RateRepository rates,
    41	            RoleRepository roles, SettingsRepository settings, ClaimLogRepository log, WatchRepository watches, HttpServletRequest http,
    42	            Audit audit, Out<BulkSettleResponse> result) {
    43	        String user = Audit.user(http);
    44	        Set<Long> selected = new HashSet<>();
    45	        for (String id : request.claimIds()) {
    46	            try {
    47	                selected.add(Long.parseLong(id.trim()));
    48	            } catch (NumberFormatException | NullPointerException e) {
    49	                // not an id: no claim on the sheet, so refused below
    50	            }
    51	        }
    52	        int requested = new HashSet<>(request.claimIds()).size();
    53	        int settled = 0;
    54	        if (sheet.archived() || Role.VIEWER.equals(roles.roleOf(sheet.id(), user))) {
    55	            result.set(new BulkSettleResponse(0, requested)); // a viewer, or an archived sheet, changes nothing
    56	            return;
    57	        }
    58	        // All or nothing: every selected claim is settled in memory first; any refusal refuses them all.
    59	        List<Claim> toSettle = new ArrayList<>();
    60	        for (Person person : people.findAll(sheet.id())) {
    61	            for (Claim claim : claims.findByPerson(sheet.id(), person.getId())) {
    62	                if (!selected.contains(claim.getId())) continue;
    63	                if (periods.closedOn(sheet.id(), claim.getDueBy()) != null) {
    64	                    result.set(new BulkSettleResponse(0, requested));
    65	                    return;
    66	                }
    67	                try {
    68	                    SettleClaim.settle(sheet, claim, user, people, rates, roles, settings);
    69	                } catch (InvalidClaimStatusException | SelfSettleException e) {
    70	                    result.set(new BulkSettleResponse(0, requested));
    71	                    return;
    72	                }
    73	                toSettle.add(claim);
    74	            }
    75	        }
    76	        if (toSettle.isEmpty() || toSettle.size() != requested) {
    77	            result.set(new BulkSettleResponse(0, requested)); // a selected id not on the sheet is refused
    78	            return;
    79	        }
    80	        int batch = claims.nextBatch(sheet.id());
    81	        BigDecimal total = BigDecimal.ZERO.setScale(2);
    82	        Rollup before = rollup(sheet, sheets, people, claims, rates, settings);
    83	        for (Claim claim : toSettle) {
    84	            claim.setSettleBatch(batch);
    85	            ClaimNumbers.giveOnSettle(sheet, claim, settings.find(sheet.id()), periods, claims);
    86	            claims.save(claim);
    87	            log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
    88	            settled++;
    89	            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
    90	                total = total.add(claim.getSettledDue());
    91	            }
    92	            audit.record(AuditClaimStatus.line(sheet, claim, user, people));
    93	            WatchNotices.lines(sheet, claim, user, people, watches).forEach(audit::record);
    94	            Rollup after = rollup(sheet, sheets, people, claims, rates, settings);
    95	            after.changesSince(before, sheet.id(), user).forEach(audit::record);
    96	            before = after;
    97	        }
    98	        audit.record("BATCH_SETTLED sheet=" + sheet.id() + " by=" + user + " batch=" + batch + " count=" + settled
    99	                + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
   100	        result.set(new BulkSettleResponse(settled, requested - settled));
   101	    }
