     8	/**
     9	 * A pool, as the screen reads it: its members in the order added, the total of their shares (a retired
    10	 * member's counting as given) and whether that total is exactly 100.00. Each member of a balanced pool
    11	 * has a cut of the sheet's pot: the pot times their share divided by the shares of the members with a cut
    12	 * added up, rounded half to even to two decimals (a retired member's, and a member held on the sheet's
    13	 * today, 0.00), with the remainder, the pot minus the cuts added up, going to the member with the
    14	 * smallest non-zero cut, the latest added on a tie (a member with no cut gets none; when no cut is
    15	 * non-zero, to the last member with a cut and a share), so the cuts total exactly the pot (each is 0.00
    16	 * when no member has a cut). A pool whose every member is retired has no cuts. A hold or a retirement changes neither the total nor whether the pool is balanced. An
    17	 * unbalanced pool, or no pot, has no cuts. A member whose dates do not include the sheet's today is
    18	 * left out entirely: not in the total, not in the balance, and no cut (not even 0.00). A pool that is a member of another has no pot of its own: its
    19	 * pot is its cut in the pool above (none when that pool has no cuts). {@code added} orders the pools as they
    20	 * were added (a larger one added later), a crew's after every pool. {@code crew} is whether it is a crew's
    21	 * pool: its lead and members at equal shares, kept by the crew (no member is added to it as to a pool).
    22	 */
    23	public record PoolResponse(String name, List<PoolMemberResponse> members, String totalShare, boolean balanced,
    24	        long added, boolean crew) {
    25	    /** Added to a crew's id for its {@code added}, so the crews' pools come after every pool. */
    26	    static final long CREW_ADDED = 1_000_000_000_000L;
    28	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
    30	    public static PoolResponse from(Pool pool, List<PoolMember> members, BigDecimal pot) {
    31	        return from(pool, members, pot, pool.id(), false);
    32	    }
    34	    /** A crew's pool: named as the crew, {@code crewId} the crew's id. */
    35	    public static PoolResponse ofCrew(Pool pool, long crewId, List<PoolMember> members, BigDecimal pot) {
    36	        return from(pool, members, pot, CREW_ADDED + crewId, true);
    37	    }
    39	    private static PoolResponse from(Pool pool, List<PoolMember> members, BigDecimal pot, long added, boolean crew) {
    40	        BigDecimal total = total(members);
    41	        boolean balanced = total.compareTo(HUNDRED) == 0;
    42	        List<BigDecimal> cuts = cutsOf(members, pot);
    43	        List<PoolMemberResponse> shown = new ArrayList<>();
    44	        for (int i = 0; i < members.size(); i++) {
    45	            shown.add(PoolMemberResponse.from(members.get(i), cuts == null ? null : cuts.get(i)));
    46	        }
    47	        return new PoolResponse(pool.name(), shown, total.toPlainString(), balanced, added, crew);
    48	    }
    50	    /** The active members' shares added up, a retired member's counting as given. */
    51	    static BigDecimal total(List<PoolMember> members) {
    52	        BigDecimal total = BigDecimal.ZERO.setScale(2);
    53	        for (PoolMember m : members) if (m.active()) total = total.add(m.share());
    54	        return total;
    55	    }
    57	    /**
    58	     * Each member's cut of the pot, in the members' order; null when the pool is unbalanced, there is no pot,
    59	     * or every member is retired.
    60	     */
    61	    static List<BigDecimal> cutsOf(List<PoolMember> members, BigDecimal pot) {
    62	        boolean allRetired = members.stream().filter(PoolMember::active).allMatch(PoolMember::retired);
    63	        return pot != null && !allRetired && total(members).compareTo(HUNDRED) == 0 ? cuts(members, pot) : null;
    64	    }
    66	    /** Whether the member has a cut: active, neither retired nor held on the sheet's today. */
    67	    private static boolean hasCut(PoolMember m) {
    68	        return m.active() && !m.retired() && !m.held();
    69	    }
    71	    private static List<BigDecimal> cuts(List<PoolMember> members, BigDecimal pot) {
    72	        BigDecimal shares = BigDecimal.ZERO;
    73	        for (PoolMember m : members) if (hasCut(m)) shares = shares.add(m.share());
    74	        List<BigDecimal> cuts = new ArrayList<>();
    75	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
    76	        int smallest = -1;
    77	        int lastShared = -1;
    78	        for (int i = 0; i < members.size(); i++) {
    79	            PoolMember m = members.get(i);
    80	            if (!m.active()) {
    81	                cuts.add(null);
    82	                continue;
    83	            }
    84	            BigDecimal cut = !hasCut(m) || shares.signum() == 0 ? BigDecimal.ZERO.setScale(2)
    85	                    : pot.multiply(m.share()).divide(shares, 2, RoundingMode.HALF_EVEN);
    86	            cuts.add(cut);
    87	            sum = sum.add(cut);
    88	            if (!hasCut(m)) continue;
    89	            if (m.share().signum() > 0) lastShared = i;
    90	            if (cut.signum() != 0 && (smallest < 0 || cut.compareTo(cuts.get(smallest)) <= 0)) smallest = i;
    91	        }
    92	        int to = smallest >= 0 ? smallest : lastShared;
    93	        if (to >= 0 && shares.signum() > 0) cuts.set(to, cuts.get(to).add(pot.subtract(sum)));
    94	        return cuts;
    95	    }
