    31	/**
    32	 * For every plan on the sheet, in the order they were added, a DRAFT claim with the plan's amount for
    33	 * every plan date (its start, then every N days; or monthly on its day of the month) up to its end and the sheet's today that has none yet,
    34	 * dated that day with an empty note. Each is checked as the claim form checks a claim (its due-by outside
    35	 * a closed period, its date not after its person's retirement): a date refused is skipped, and tried again
    36	 * next time. Each claim made is saved, logged and audited as one added by the form. Like a bulk action, a
    37	 * viewer, or anyone on an archived sheet, goes through and makes none.
    38	 * <p>
    39	 * A plan naming a descendant sheet makes its claims there instead, for the person of the same name on that
    40	 * sheet (none when there is no such person), by that sheet's rules (its terms, holidays, periods and today)
    41	 * and in that sheet's audit, followed by that sheet's rollup lines; its dates still run up to this sheet's
    42	 * today, and the plan still counts what it made. A descendant archived, or on which the user is a viewer,
    43	 * gets none.
    44	 */
    45	public class AddPlanClaims {
    46	    public void add(@Val Sheet sheet, PlanRepository plans, PersonRepository people, ClaimRepository claims,
    47	            PeriodRepository periods, RateRepository rates, SettingsRepository settings, ClaimLogRepository log,
    48	            HolidayRepository holidays, RoleRepository roles, SheetRepository sheets, HttpServletRequest request, Audit audit, Out<GenerateResponse> result) {
    49	        Settings terms = settings.find(sheet.id());
    50	        Set<LocalDate> holidayDates = holidays.dates(sheet.id());
    51	        String user = Audit.user(request);
    52	        if (sheet.archived() || Role.VIEWER.equals(roles.roleOf(sheet.id(), user))) {
    53	            result.set(new GenerateResponse(0)); // a viewer, or an archived sheet, makes nothing
    54	            return;
    55	        }
    56	        int made = 0;
    57	        Map<String, Rollup> touched = new LinkedHashMap<>();
    58	        for (Plan plan : plans.findAll(sheet.id())) {
    59	            Person owner = people.find(sheet.id(), plan.personId());
    60	            if (owner == null) continue;
    61	            Sheet on = sheet;
    62	            Person person = owner;
    63	            if (plan.target() != null) {
    64	                on = sheets.find(plan.target());
    65	                if (on == null || on.archived() || Role.VIEWER.equals(roles.roleOf(on.id(), user))) continue;
    66	                person = people.findByName(on.id(), owner.getName());
    67	                if (person == null) continue;
    68	            }
    69	            Settings onTerms = on == sheet ? terms : settings.find(on.id());
    70	            Set<LocalDate> onHolidays = on == sheet ? holidayDates : holidays.dates(on.id());
    71	            Set<LocalDate> done = plans.made(plan.id());
    72	            LocalDate last = plan.end().isBefore(sheet.today()) ? plan.end() : sheet.today();
    73	            for (LocalDate date : plan.datesUpTo(last)) {
    74	                if (done.contains(date)) continue;
    75	                Claim claim = new Claim(null, on.id(), person.getId(), plan.amount(), date, "",
    76	                        ClaimStatus.DRAFT, null, null, null);
    77	                claim.fixDueBy(onTerms.termsFor(person, on.today()), onHolidays);
    78	                try {
    79	                    new CheckClaimPeriod().check(on, claim, periods);
    80	                    new CheckClaimRetired().check(on, claim, people);
    81	                } catch (ClosedPeriodException | RetiredPersonException e) {
    82	                    continue;
    83	                }
    84	                if (on != sheet && !touched.containsKey(on.id())) {
    85	                    touched.put(on.id(), Rollup.of(on.id(), on.today(), people, claims, rates, onTerms));
    86	                }
    87	                claim.setLateEntry(periods.softClosedOn(on.id(), claim.getDueBy()) != null);
    88	                claims.save(claim);
    89	                plans.recordMade(plan.id(), date, claim.getId());
    90	                log.record(claim, user, on.today(), LogClaimStatus.due(on, claim, people, rates, settings));
    91	                new AuditClaimAdded().audit(on, person, claim, request, audit);
    92	                made++;
    93	            }
    94	        }
    95	        // Each descendant written to: the figures the plans moved there, in its own audit.
    96	        for (Map.Entry<String, Rollup> e : touched.entrySet()) {
    97	            Rollup after = Rollup.of(e.getKey(), sheets.today(e.getKey()), people, claims, rates,
    98	                    settings.find(e.getKey()));
    99	            after.changesSince(e.getValue(), e.getKey(), user).forEach(audit::record);
   100	        }
   101	        result.set(new GenerateResponse(made));
   102	    }
   103	}
