    22	/**
    23	 * Gives the plan's new amount to the claims it generated that are still DRAFT, in the order it made them,
    24	 * each as the claim form edits it: saved with the signed-in user as its last editor and audited as
    25	 * CLAIM_EDITED. A draft the editor would refuse (its editor open by another user, its due-by inside a
    26	 * closed period, its lines' total another amount) keeps its amount, as does a claim in any other status
    27	 * and a draft that already has the new amount. Drafts the plan made on a descendant sheet are edited
    28	 * there, in that sheet's audit, followed by that sheet's rollup lines.
    29	 */
    30	public class EditPlanDrafts {
    31	    public void edit(@Val PlanAmount input, @Val Sheet sheet, @Val Plan plan, PlanRepository plans,
    32	            ClaimRepository claims, ClaimLineRepository lines, PeriodRepository periods, PersonRepository people,
    33	            RateRepository rates, SettingsRepository settings, SheetRepository sheets, HttpServletRequest request,
    34	            Audit audit) {
    35	        String user = Audit.user(request);
    36	        BigDecimal amount = input.amount();
    37	        Sheet on = plan.target() == null ? sheet : sheets.find(plan.target());
    38	        if (on == null) return;
    39	        Rollup before = on == sheet ? null
    40	                : Rollup.of(on.id(), on.today(), people, claims, rates, settings.find(on.id()));
    41	        boolean edited = false;
    42	        for (long id : plans.madeClaims(plan.id())) {
    43	            Claim claim = claims.find(on.id(), id);
    44	            if (claim == null || claim.getStatus() != ClaimStatus.DRAFT) continue;
    45	            if (claim.getAmount().compareTo(amount) == 0) continue;
    46	            if (claims.lockedByOther(claim, user, on.today())) continue;
    47	            BigDecimal total = lines.total(claim);
    48	            if (total != null && total.compareTo(amount) != 0) continue;
    49	            try {
    50	                new CheckClaimPeriod().check(on, claim, periods);
    51	            } catch (ClosedPeriodException e) {
    52	                continue;
    53	            }
    54	            claim.setAmount(amount);
    55	            claim.setEditedBy(user);
    56	            claims.save(claim);
    57	            audit.record(ClaimAudit.line("CLAIM_EDITED", on, user, people.find(on.id(), claim.getPersonId()), claim));
    58	            edited = true;
    59	        }
    60	        // A descendant written to: the figures the edits moved there, in its own audit.
    61	        if (before != null && edited) {
    62	            Rollup after = Rollup.of(on.id(), sheets.today(on.id()), people, claims, rates, settings.find(on.id()));
    63	            after.changesSince(before, on.id(), user).forEach(audit::record);
    64	        }
    65	    }
    66	}
