    13	/**
    14	 * Splits the paste into lines (blank lines skipped) and checks each by the claim form's rules (a
    15	 * note ending {@code " #<reference>"} gives the claim's reference); the
    16	 * first line that fails refuses the whole paste. A paste with no lines is refused too.
    17	 */
    18	public class ValidatePaste {
    19	    public void validate(@RequestBody PasteRequest request, Out<PasteLines> linesOut) throws InvalidClaimException {
    20	        String text = request == null || request.text() == null ? "" : request.text();
    21	        List<PasteLine> lines = new ArrayList<>();
    22	        int number = 0;
    23	        for (String raw : text.split("\\r?\\n|\\r")) {
    24	            number++;
    25	            if (raw.isBlank()) continue;
    26	            String[] fields = raw.split(",", 4);
    27	            if (fields.length < 2) throw new InvalidClaimException("Line " + number + ": name,amount,date,note");
    28	            String name;
    29	            try {
    30	                name = PersonRequest.checkName(fields[0]);
    31	            } catch (InvalidPersonException e) {
    32	                throw new InvalidClaimException("Line " + number + ": " + e.getMessage());
    33	            }
    34	            String date = fields.length > 2 ? fields[2] : "";
    35	            String note = fields.length > 3 ? fields[3].trim() : "";
    36	            // A note ending " #<reference>" gives the claim's reference: that part is not the note's.
    37	            String ref = "";
    38	            int hash = note.lastIndexOf(" #");
    39	            if (hash >= 0) {
    40	                ref = note.substring(hash + 2);
    41	                note = note.substring(0, hash);
    42	            }
    43	            try {
    44	                ClaimInput claim = ClaimInput.from(new ClaimRequest(fields[1], date, note, "", ref));
    45	                lines.add(new PasteLine(name, claim));
    46	            } catch (InvalidClaimException e) {
    47	                throw new InvalidClaimException("Line " + number + ": " + e.getMessage());
    48	            }
    49	        }
    50	        if (lines.isEmpty()) throw new InvalidClaimException("Paste at least one line of name,amount,date,note");
    51	        linesOut.set(new PasteLines(lines));
    52	    }
    53	}
