   126	    public static Map<Long, BigDecimal> heldParts(List<Person> everyone, List<Claim> sheetClaims,
   127	            Map<Long, List<ClaimShare>> shares, List<Rate> all, Settings settings, LocalDate today) {
   128	        Map<Long, BigDecimal> held = new HashMap<>();
   129	        for (Person owner : everyone) {
   130	            for (Claim claim : sheetClaims) {
   131	                List<ClaimShare> of = shares.get(claim.getId());
   132	                if (of == null || claim.getPersonId() != owner.getId()) continue;
   133	                if (!claim.counts(owner.heldOn(claim.getDate(), today), today)) continue;
   134	                BigDecimal figure = ClaimFigure.withLate(claim, all, owner.gradeOn(claim.getDate()), settings, today);
   135	                if (figure == null) continue;
   136	                for (ClaimShare share : of) {
   137	                    BigDecimal part = share.partOf(claim, figure, holder(everyone, share), all, settings, today);
   138	                    if (part != null) held.merge(share.personId(), part, BigDecimal::add);
   139	                }
   140	            }
   141	        }
   142	        return held;
   143	    }
