   145	    /** A claim's figure less its holders' parts (the whole figure when it has no shares; a part with no rate is 0.00). */
   146	    public static BigDecimal ownPart(Claim claim, BigDecimal figure, List<ClaimShare> shares, List<Person> everyone,
   147	            List<Rate> all, Settings settings, LocalDate today) {
   148	        if (shares == null) return figure;
   149	        BigDecimal own = figure;
   150	        for (ClaimShare share : shares) {
   151	            BigDecimal part = share.partOf(claim, figure, holder(everyone, share), all, settings, today);
   152	            if (part != null) own = own.subtract(part);
   153	        }
   154	        return own;
   155	    }
