     5	export type Dup = { name: string; date: string; amount: string; count: number };
     7	/**
     8	 * The duplicate claims: for each person, date and amount with two or more claims (VOID and
     9	 * DELETED ones left out), people in list order, then by date, then by amount (as a number).
    10	 */
    11	export function duplicates(people: Person[], claims: Claim[]): Dup[] {
    12	  const out: Dup[] = [];
    13	  for (const p of people) {
    14	    const groups = new Map<string, Dup>();
    15	    for (const c of claims) {
    16	      if (c.personId !== p.id || c.status === 'VOID' || c.status === 'DELETED') continue;
    17	      const key = `${c.date} ${c.amount}`;
    18	      const g = groups.get(key);
    19	      if (g) g.count++;
    20	      else groups.set(key, { name: p.name, date: c.date, amount: c.amount, count: 1 });
    21	    }
    22	    const dups = [...groups.values()].filter((g) => g.count >= 2);
    23	    dups.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : Number(a.amount) - Number(b.amount)));
    24	    out.push(...dups);
    25	  }
    26	  return out;
    27	}
